    const ready: RetryItem[] = [];
    const ticks = [...this.buckets.keys()].filter((tick) => tick <= boundary).sort((a, b) => a - b);
    for (const tick of ticks) {
      for (const item of this.buckets.get(tick)!) {
        this.ids.delete(item.id);
        ready.push(item);
